export function icon(name, cls = '') {
    const svg = icons[name];
    if (!svg)
        return '';
    return `<svg class="${cls}" fill="none" stroke="currentColor" viewBox="0 0 24 24">${svg.replace(/<svg[^>]*>/, '').replace('</svg>', '')}</svg>`;
}
